/* Wall-clock weekly layout in the schedule's explicit IANA timezone. */
const WeeklyCalendar=(()=>{
 const HOUR=64,MINUTE=HOUR/60;
 const formatters=new Map(),instantCache=new Map();
 function local(value,timezone){if(!formatters.has(timezone))formatters.set(timezone,new Intl.DateTimeFormat('sv-SE',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}));const parts=formatters.get(timezone).format(new Date(value));const [day,time]=parts.split(' ');const [h,m]=time.split(':').map(Number);return {day,minute:h*60+m,time}}
 function plus(day,n){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
 function instants(day,minute,timezone){
  if(minute===1440){day=plus(day,1);minute=0}
  const key=timezone+'|'+day+'|'+minute;if(instantCache.has(key))return instantCache.get(key);
  const [y,m,d]=day.split('-').map(Number),wall=Date.UTC(y,m-1,d,Math.floor(minute/60),minute%60),offsets=new Set();
  for(const hours of [-36,0,36]){const sample=wall+hours*3600000,part=local(sample,timezone);offsets.add(Date.parse(part.day+'T'+part.time+':00Z')-sample)}
  const result=[...offsets].map(offset=>wall-offset).filter(value=>{const p=local(value,timezone);return p.day===day&&p.minute===minute}).sort((a,b)=>a-b);if(instantCache.size>10000)instantCache.clear();instantCache.set(key,result);return result;
 }
 function secondaryHours(weekStart,hour,timezone,secondary){return Array.from({length:7},(_,i)=>{const day=plus(weekStart,i),values=instants(day,hour*60,timezone);return {day,weekday:i,values:values.map(value=>{const p=local(value,secondary);return {time:p.time,day:p.day,dayOffset:Math.round((Date.parse(p.day+'T00:00Z')-Date.parse(day+'T00:00Z'))/86400000)}})}})}
 function selection(day,anchor,current,timezone){const start=Math.min(anchor,current),end=Math.max(anchor,current)+30;
  for(let m=start;m<end;m+=30)if(instants(day,m,timezone).length!==1)return null;
  const from=instants(day,start,timezone),to=instants(day,end,timezone);if(from.length!==1||to.length!==1)return null;
  return {value:day+'T'+String(Math.floor(start/60)).padStart(2,'0')+':'+String(start%60).padStart(2,'0'),start,end,duration:(to[0]-from[0])/60000};
 }
 function segments(rows,day,timezone){return rows.flatMap(row=>{const start=local(row.starts_at,timezone),end=local(row.ends_at,timezone);if(start.day>day||end.day<day||(end.day===day&&end.minute===0))return [];let from=start.day<day?0:start.minute,to=end.day>day?1440:end.minute;if(to<=from&&start.day===end.day&&start.day===day)to=Math.min(1440,from+(new Date(row.ends_at)-new Date(row.starts_at))/60000);if(to<=from)return [];return [{row,start:from,end:to,visualEnd:Math.min(1440,Math.max(to,from+20)),continued:start.day<day,continues:end.day>day&&end.minute!==0}]})}
 function lanes(events){const sorted=events.map(e=>({...e})).sort((a,b)=>a.start-b.start||b.end-a.end||a.row.id-b.row.id);let group=[],ends=[],maxEnd=-1;const result=[];function flush(){for(const e of group)result.push({...e,lanes:ends.length});group=[];ends=[];maxEnd=-1}for(const e of sorted){if(group.length&&e.start>=maxEnd)flush();let lane=ends.findIndex(end=>end<=e.start);if(lane<0)lane=ends.length;ends[lane]=e.visualEnd??e.end;group.push({...e,lane});maxEnd=Math.max(maxEnd,e.visualEnd??e.end)}flush();return result}
 function node(tag,value,className){const e=document.createElement(tag);if(value!==undefined)e.textContent=value;if(className)e.className=className;return e}
 function render(root,rows,options){const {weekStart,timezone,onCreate,onOpen,onInvalid=()=>{},secondaryZone='Europe/Berlin'}=options;const savedTop=root.scrollTop,initialized=root.dataset.initialized==='true';root.dataset.initialized='true';root.replaceChildren();root.className='time-calendar';root.setAttribute('aria-label','Недельный календарь, часовой пояс '+timezone);root.tabIndex=0;
 const zoneNames={'Europe/Berlin':'Берлин','Europe/Moscow':'Москва','Europe/London':'Лондон','UTC':'UTC'},zoneName=zoneNames[secondaryZone]||secondaryZone;
 const secondary=secondaryZone?Array.from({length:24},(_,h)=>secondaryHours(weekStart,h,timezone,secondaryZone)):[];
 const labelTime=values=>values.map(v=>v.time+(v.dayOffset<0?' (−1д.)':v.dayOffset>0?' (+1д.)':'')).join(' / ')||'—';
 const changed=(hour,day)=>secondaryZone&&labelTime(secondary[hour][day].values)!==labelTime(secondary[hour][0].values);
 const week=node('div',undefined,'time-week'),now=local(new Date(),timezone),corner=node('div',zoneNames[timezone]||timezone,'time-corner');week.append(corner);week.classList.toggle('has-secondary-zone',!!secondaryZone);if(secondaryZone)week.append(node('div',zoneName,'time-corner secondary-corner'));
 for(let i=0;i<7;i++){const day=plus(weekStart,i),hasChange=secondaryZone&&secondary.some((_,h)=>changed(h,i)),head=node('div',undefined,'time-day-heading'+(day===now.day?' is-today':''));head.append(node('span',new Date(day+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',weekday:'short'})),node('strong',new Date(day+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'short'})));if(hasChange)head.append(node('small','Перевод часов · '+zoneName,'timezone-change-heading'));week.append(head)}
 const axis=node('div',undefined,'time-axis');axis.style.height=(24*HOUR)+'px';for(let h=0;h<24;h++){const label=node('span',String(h).padStart(2,'0')+':00');label.style.top=(h*HOUR)+'px';axis.append(label)}week.append(axis);
 if(secondaryZone){const secondAxis=node('div',undefined,'time-axis secondary-axis');secondAxis.style.height=(24*HOUR)+'px';for(let h=0;h<24;h++){const label=node('div',labelTime(secondary[h][0].values),'secondary-hour');label.style.top=(h*HOUR)+'px';label.title='Шкала на '+weekStart+'. Красные подписи в днях показывают время после перевода часов.';secondAxis.append(label)}week.append(secondAxis)}
 let drag=null,suppressClickUntil=0;
 const clearSelection=()=>{if(drag){drag.highlight.remove();if(drag.column.hasPointerCapture?.(drag.id))drag.column.releasePointerCapture(drag.id);drag=null}};
 const escape=event=>{if(event.key==='Escape'&&drag){suppressClickUntil=Date.now()+500;clearSelection()}};document.addEventListener('keydown',escape);
 const columns=[];for(let i=0;i<7;i++){const day=plus(weekStart,i),column=node('div',undefined,'time-day'+(day===now.day?' is-today':''));column.style.height=(24*HOUR)+'px';column.setAttribute('aria-label',day);columns.push({day,column});
 if(secondaryZone)for(let h=0;h<24;h++)if(changed(h,i)){const correction=node('div',zoneName+' '+labelTime(secondary[h][i].values),'timezone-correction');correction.style.top=(h*HOUR)+'px';correction.title=day+' · '+zoneName+': '+labelTime(secondary[h][i].values)+' (после перевода часов)';column.append(correction)}

 column.onpointermove=event=>{if(!drag||drag.column!==column||event.pointerId!==drag.id)return;if(Math.abs(event.clientY-drag.origin)>4)drag.moved=true;const viewport=root.getBoundingClientRect();if(event.clientY>viewport.bottom-24)root.scrollTop+=16;else if(event.clientY<viewport.top+90)root.scrollTop-=16;const current=Math.max(0,Math.min(1410,Math.floor((event.clientY-column.getBoundingClientRect().top)/(30*MINUTE))*30));drag.current=current;drag.highlight.style.top=(Math.min(current,drag.anchor)*MINUTE)+'px';drag.highlight.style.height=((Math.abs(current-drag.anchor)+30)*MINUTE)+'px';const selected=selection(day,drag.anchor,current,timezone);drag.highlight.textContent=selected?selected.value.slice(11)+' · '+selected.duration+' мин':'Перевод часов';};
 column.onpointerup=event=>{if(!drag||drag.column!==column||event.pointerId!==drag.id)return;const chosen=drag,moved=chosen.moved,selected=selection(day,chosen.anchor,chosen.current,timezone);clearSelection();suppressClickUntil=Date.now()+500;if(!moved){const single=selection(day,chosen.anchor,chosen.anchor,timezone);if(single&&instants(day,single.start,timezone)[0]>=Date.now())onCreate(single.value);return}if(!selected){onInvalid('Этот интервал затрагивает неоднозначное время перевода часов. Выберите другое время.');return}const first=instants(day,selected.start,timezone)[0];if(first<Date.now()){onInvalid('Выберите будущее время для занятия.');return}onCreate(selected.value,selected.duration);};
 column.onpointercancel=()=>{suppressClickUntil=Date.now()+500;clearSelection()};
 for(let slot=0;slot<48;slot++){const minute=slot*30,h=Math.floor(minute/60),m=minute%60,time=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');const button=node('button',undefined,'time-slot');button.type='button';button.style.top=(minute*MINUTE)+'px';button.style.height=(30*MINUTE)+'px';button.setAttribute('aria-label','Создать урок '+day+' в '+time);button.title=day+' · '+time;const valid=instants(day,minute,timezone).length===1;button.disabled=!valid||day<now.day||(day===now.day&&minute<now.minute);if(!valid)button.title='Неоднозначное или отсутствующее время из-за перевода часов';button.onclick=event=>{if(event.detail!==0&&Date.now()<suppressClickUntil)return;onCreate(day+'T'+time)};button.onpointerdown=event=>{if(event.pointerType!=='mouse'||event.button!==0||button.disabled)return;event.preventDefault();clearSelection();const highlight=node('div',time+' · 30 мин','calendar-selection');highlight.style.top=(minute*MINUTE)+'px';highlight.style.height=(30*MINUTE)+'px';column.append(highlight);drag={id:event.pointerId,anchor:minute,current:minute,column,highlight,origin:event.clientY,moved:false};column.setPointerCapture(event.pointerId)};column.append(button)}
 for(const e of lanes(segments(rows,day,timezone))){const row=e.row,start=local(row.starts_at,timezone),end=local(row.ends_at,timezone),status={scheduled:'Запланировано',completed:'Проведено',cancelled:'Отменено'}[row.status]||row.status;const button=node('button',undefined,'calendar-event '+row.status);button.type='button';button.style.top=(e.start*MINUTE)+'px';button.style.height=Math.max(1,(e.visualEnd-e.start)*MINUTE-2)+'px';button.style.left='calc('+(e.lane*100/e.lanes)+'% + 2px)';button.style.width='calc('+(100/e.lanes)+'% - 4px)';const period=(e.continued?'Продолжение · ':'')+start.time+'–'+end.time;button.append(node('strong',row.student_name||'Занятие'),node('span',period),node('span',row.topic||status));const additional=secondaryZone?local(row.starts_at,secondaryZone):null;button.title=[row.student_name,period,row.topic,status,additional?secondaryZone+': '+additional.day+' '+additional.time:null,row.student_timezone?'У ученика ('+row.student_timezone+'): '+local(row.starts_at,row.student_timezone).day+' '+local(row.starts_at,row.student_timezone).time:null].filter(Boolean).join(' · ');button.setAttribute('aria-label',button.title);button.onclick=()=>onOpen(row);column.append(button)}week.append(column)}root.append(week);
 const marker=node('div',undefined,'calendar-now');marker.setAttribute('aria-hidden','true');const update=()=>{const current=local(new Date(),timezone),target=columns.find(c=>c.day===current.day);if(target){marker.style.top=(current.minute*MINUTE)+'px';target.column.append(marker)}else marker.remove()};update();const timer=setInterval(update,60000);
 root.scrollTop=initialized?savedTop:8*HOUR;return ()=>{clearInterval(timer);clearSelection();document.removeEventListener('keydown',escape)}}
 return {local,plus,instants,secondaryHours,selection,segments,lanes,render};
})();
